from abc import ABC, abstractmethod
import torch.utils.data


class IDataLoader(ABC):
    """Interface for data loaders."""

    @abstractmethod
    def load_data(self):
        """Return a DataLoader instance."""
        pass

    @abstractmethod
    def __len__(self):
        """Return number of batches."""
        pass


class IDatasetFactory(ABC):
    """Interface for dataset factories."""

    @abstractmethod
    def get_by_name(self, dataset_name, *args, **kwargs):
        """Return a dataset instance by name."""
        pass


class IDataset(ABC):
    """Interface for datasets."""

    @abstractmethod
    def __len__(self):
        """Return number of samples."""
        pass

    @abstractmethod
    def __getitem__(self, idx):
        """Return a sample at index idx."""
        pass


class ICustomDatasetDataLoader:
    """Interface for custom dataset data loader (concrete implementation of IDataLoader)."""

    @abstractmethod
    def __init__(self, dataset, batch_size, shuffle, num_threads):
        """Initialize with dataset and loading parameters."""
        pass

    @abstractmethod
    def load_data(self):
        """Return the underlying DataLoader."""
        pass

    @abstractmethod
    def __len__(self):
        """Return number of batches."""
        pass
